'use strict';
(()=>{
 const db=window.LWU_NEW_SUBJECTS,main=document.getElementById('subjectRoot');if(!db||!main)return;
 const qs=new URLSearchParams(location.search),kind=document.body.dataset.newKind||'science',area=db[kind]||db.science;
 const keys=Object.keys(area),topic=area[qs.get('topic')]?qs.get('topic'):keys[0],lesson=area[topic],quiz=document.body.dataset.newQuiz==='true';
 const prefix=kind==='science'?'science-discovery':'smarter-maths';
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const speak=t=>{if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='en-IN';u.rate=.83;window.speechSynthesis.speak(u)};
 const shuffle=a=>[...a].sort(()=>Math.random()-.5);
 const loc=(key,isQuiz=false)=>`${prefix}${isQuiz?'-quiz':''}.html?topic=${key}`;
 const name=(key)=>area[key].title;
 const at=keys.indexOf(topic),previous=keys[at-1],next=keys[at+1];
 const label=document.getElementById('subjectTitle'),desc=document.getElementById('subjectDescription'),nav=document.getElementById('subjectNav');
 document.title=lesson.title+(quiz?' Quiz':'')+' | LearnWithUs';if(label)label.textContent=lesson.icon+' '+lesson.title+(quiz?' Quiz':'');if(desc)desc.textContent=lesson.description;
 if(nav)nav.innerHTML=keys.map(k=>`<a href="${loc(k,quiz)}" ${k===topic?'aria-current="page"':''}>${area[k].icon} ${escape(area[k].title)}</a>`).join('');
 const voiceFeedback=(good,answer,el)=>{const text=good?`Correct answer! It is ${answer}.`:`Wrong answer. The correct answer is ${answer}.`;el.textContent=text;speak(text)};
 const chart=(q)=>!q.graph?'':`<div class="subject-chart" role="img" aria-label="Bar chart: ${q.graph.map(([n,v])=>n+': '+v).join(', ')}">${q.graph.map(([n,v])=>`<div class="subject-chart-row"><strong>${escape(n)}</strong><span class="subject-chart-bar"><span style="width:${v*8}%"></span></span><b>${v}</b></div>`).join('')}</div>`;
 const visual=()=>{const symbols=kind==='science'?({'plant-life-cycle':['🌰','🌱','🌿','🌷'],'water-cycle':['☀️','💧','☁️','🌧️'],'day-night':['🌄','☀️','🌅','🌙'],'seasons':['🌸','☀️','🍂','❄️'],'weather':['🌦️','☁️','🌧️','🌬️'],'human-body':['🧠','❤️','🫁','🦴'],'five-senses':['👀','👂','👃','👅','🖐️'],'animal-habitats':['🌲','🏜️','🌊','🏔️'],'magnets':['🧲','📎','🧭'],'sink-float':['🪵','🚢','🪙'],'safe-experiments':['🔬','🌱','🧲','🌤️']})[topic]:( {'compare-numbers':['4','<','7'],'skip-counting':['2','4','6','8'],'number-patterns':['1','3','5','7'],'mental-maths':['8','+','7','=','15'],'word-problems':['📚','➕','🧠'],'estimation':['🎯','≈','💭'],'3d-shapes':['🎲','⚽','🥫','🍦'],'symmetry':['🦋','|','🦋'],'geometry':['📏','📐','🔺'],'data-graphs':['▂','▄','▆','█']} )[topic];return '<div class="subject-mini-visual" aria-hidden="true">'+(symbols||[]).map(x=>`<span class="mini-symbol">${x}</span>`).join('')+'</div>'};
 const actions=()=>`<div class="subject-actions"><a class="subject-button" href="${previous?loc(previous):kind==='science'?'planets.html':'measurement.html'}">← Previous: ${escape(previous?name(previous):kind==='science'?'Planets':'Measurement')}</a><a class="subject-button primary" href="${loc(topic,true)}">Start ${escape(lesson.title)} Quiz →</a>${next?`<a class="subject-button" href="${loc(next)}">Next: ${escape(name(next))} →</a>`:'<span class="subject-button subject-empty" aria-hidden="true"></span>'}</div>`;
 if(!quiz){
   const facts=lesson.facts;const translated=window.LWUExplain?.get?.(kind,topic)||'';const bilingual=translated?`<p class="studio-translation">${escape(translated)}</p>`:'';
   main.innerHTML=`<section class="subject-concept"><span class="subject-branch-tag">${kind==='science'?'Science & Discovery':'Smarter Maths'} · Learn</span><h2>Explore ${escape(lesson.title)}</h2><p>${escape(lesson.description)}</p>${bilingual}${visual()}<ol class="subject-learning-steps"><li>Explore each example and hear its meaning.</li><li>Think about where you might notice it in daily life.</li><li>Try the practise question, then open the dedicated quiz.</li></ol><div class="subject-cards">${facts.map(x=>`<article class="subject-card"><strong>${escape(x.term)}</strong><small>${escape(x.detail)}</small><button class="subject-button" data-hear="${escape(x.term)}: ${escape(x.detail)}" type="button">🔊 Hear</button></article>`).join('')}</div>${kind==='science'?'<p class="subject-safety-note">🔎 Explore safely: ask a grown-up before handling water, magnets, seeds or experiment materials. Never taste experiment materials or handle electric devices near water.</p>':'<p class="subject-safety-note">💡 Tip: explain how you got your answer before choosing it. Different strategies can lead to the same correct result.</p>'}</section><section class="subject-practice"><span class="subject-branch-tag">Practise</span><h2>Answer three practice questions</h2><p>Choose an answer, read the feedback, and continue to the next question.</p><p id="subjectPracticeCount" aria-live="polite">Question 1 of 3</p><div id="practiceArea"></div></section><section class="subject-concept lw-journey-footer"><p class="eyebrow">Learn → Practise → Quiz</p><h2>🎯 Ready for the ${escape(lesson.title)} challenge?</h2><p>Use what you just practised in a focused quiz and keep your learning progress moving.</p>${actions()}</section>`;
   main.querySelectorAll('[data-hear]').forEach(b=>b.onclick=()=>speak(b.dataset.hear));
   let pos=0;const areaEl=document.getElementById('practiceArea');const exercise=()=>{
    const q=lesson.questions[pos%lesson.questions.length];pos++;const indicator=document.getElementById('subjectPracticeCount');if(indicator)indicator.textContent='Question '+Math.min(pos,3)+' of 3';
    areaEl.innerHTML=chart(q)+`<h3>${escape(q.q)}</h3><div class="subject-options">${shuffle(q.o).map(o=>`<button type="button">${escape(o)}</button>`).join('')}</div><p class="subject-feedback" role="status" aria-live="polite"></p><button class="subject-button" type="button" id="newSubjectPractice">Another question →</button>`;
    const buttons=[...areaEl.querySelectorAll('.subject-options button')],msg=areaEl.querySelector('.subject-feedback');buttons.forEach(b=>b.onclick=()=>{buttons.forEach(n=>{n.disabled=true;if(n.textContent===q.a)n.classList.add('correct')});if(b.textContent!==q.a)b.classList.add('wrong');voiceFeedback(b.textContent===q.a,q.a,msg)});areaEl.querySelector('#newSubjectPractice').onclick=()=>{if(pos<3)exercise();else{areaEl.querySelector('#newSubjectPractice').disabled=true;areaEl.querySelector('#newSubjectPractice').textContent='Practice complete ✓';document.querySelector('.subject-concept:last-of-type')?.scrollIntoView({behavior:'smooth',block:'nearest'})}};
   };exercise();window.LearnWithUs?.recordComplete?.(prefix+'.html?topic='+topic);return;
 }
 const questions=shuffle(lesson.questions);let index=0,score=0;
 const round=()=>{
  if(index>=questions.length){
   main.innerHTML=`<section class="subject-quiz-panel"><p class="subject-progress">Quiz finished</p><div class="subject-score">${score} / ${questions.length}</div><p>${score>=8?'Wonderful! You understand many of these ideas.':'Good effort! Revisit the lesson and practise the questions you missed.'}</p><div id="sharedScoreCard"></div><div class="subject-actions"><button class="subject-button primary" id="subjectAgain" type="button">Try again</button><a class="subject-button" href="${loc(topic)}">← Review lesson</a><a class="subject-button" href="quiz-hub.html">Quiz Hub →</a></div></section>`;
   window.renderLearnWithUsScoreCard?.({container:document.getElementById('sharedScoreCard'),score,total:questions.length,title:lesson.title+' Quiz',subtitle:kind==='science'?'Science & Discovery':'Smarter Maths',filename:'learnwithus-'+topic+'-score.svg',url:loc(topic,true)});
   window.LearnWithUs?.recordQuiz?.(lesson.title+' Quiz',score,questions.length,loc(topic,true));main.querySelector('#subjectAgain').onclick=()=>location.reload();return;
  }
  const q=questions[index];main.innerHTML=`<section class="subject-quiz-panel"><p class="subject-progress">Question ${index+1} of ${questions.length}</p><h2>${escape(q.q)}</h2>${chart(q)}<div class="subject-options">${shuffle(q.o).map(a=>`<button type="button">${escape(a)}</button>`).join('')}</div><p class="subject-feedback" role="status" aria-live="polite"></p><button class="subject-button primary" id="nextSubjectQuestion" hidden>${index===questions.length-1?'See score →':'Next →'}</button></section>`;
  const buttons=[...main.querySelectorAll('.subject-options button')],msg=main.querySelector('.subject-feedback'),nextBtn=main.querySelector('#nextSubjectQuestion');buttons.forEach(btn=>btn.onclick=()=>{if(!nextBtn.hidden)return;const good=btn.textContent===q.a;if(good)score++;buttons.forEach(x=>{x.disabled=true;if(x.textContent===q.a)x.classList.add('correct')});if(!good)btn.classList.add('wrong');voiceFeedback(good,q.a,msg);window.LWUSmart?.recordAnswer?.(q.q,btn.textContent,q.a,{title:lesson.title+' Quiz',url:loc(topic,true),category:kind==='science'?'Science':'Maths',explanation:q.explanation||(lesson.facts.find(f=>f.term.toLowerCase()===String(q.a).toLowerCase())?.detail||('Review '+lesson.title+': '+lesson.description))});nextBtn.hidden=false;nextBtn.focus()});nextBtn.onclick=()=>{index++;round()};
 };round();
})();
